'use client'

import { useState, useEffect } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Calendar, Users, Clock, Trophy } from 'lucide-react'
import Link from 'next/link'
import { getCompetitions, getAvailableTeachers } from '@/app/actions/competitions'
import type { Competition } from '@prisma/client'

// 定义类型
interface CompetitionWithLevel extends Competition {
  level?: string
  isExpired?: boolean
  isRegistered?: boolean
}

export default function CompetitionsPage() {
  const [competitions, setCompetitions] = useState<CompetitionWithLevel[]>([])
  const [teachers, setTeachers] = useState<Array<{
    id: string
    name: string
    teacherNo: string
    department?: string | null
  }>>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [competitionsData, teachersData] = await Promise.all([
          getCompetitions(),
          getAvailableTeachers()
        ])
        setCompetitions(competitionsData)
        setTeachers(teachersData)
      } catch (error) {
        console.error('获取数据失败:', error)
      } finally {
        setLoading(false)
      }
    }

    fetchData()
  }, [])

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    }).format(date)
  }

  // 获取分类标签颜色
  const getCategoryColor = (category: string) => {
    const colors: Record<string, string> = {
      'TECHNICAL': 'bg-blue-100 text-blue-800 border-blue-200',
      'PROGRAMMING': 'bg-green-100 text-green-800 border-green-200',
      'AI': 'bg-purple-100 text-purple-800 border-purple-200',
      'LANGUAGE': 'bg-yellow-100 text-yellow-800 border-yellow-200',
      'INNOVATION': 'bg-pink-100 text-pink-800 border-pink-200'
    }
    return colors[category] || 'bg-gray-100 text-gray-800 border-gray-200'
  }

  // 获取级别标签颜色
  const getLevelColor = (level: string) => {
    const colors: Record<string, string> = {
      '国际级': 'bg-gradient-to-r from-red-500 to-red-600 text-white border-red-700 shadow-red',
      '国家级': 'bg-gradient-to-r from-yellow-500 to-orange-500 text-white border-yellow-600 shadow-yellow',
      '省级': 'bg-gradient-to-r from-blue-500 to-blue-600 text-white border-blue-700 shadow-blue',
      '市级': 'bg-gradient-to-r from-green-500 to-green-600 text-white border-green-700 shadow-green',
      '校级': 'bg-gray-100 text-gray-700 border-gray-300'
    }
    return colors[level] || 'bg-gray-100 text-gray-700 border-gray-300'
  }

  const getCategoryLabel = (category: string) => {
    const labels: Record<string, string> = {
      TECHNICAL: '技术类',
      PROGRAMMING: '编程类',
      AI: '人工智能',
      LANGUAGE: '语言类',
      INNOVATION: '创新类'
    }
    return labels[category] || '其他'
  }

  // 竞赛卡片组件
  function CompetitionCard({ 
    competition, 
    formatDate, 
    getCategoryColor, 
    getCategoryLabel,
    getLevelColor,
    teachers
  }: {
    competition: CompetitionWithLevel
    formatDate: (date: Date) => string
    getCategoryColor: (category: string) => string
    getCategoryLabel: (category: string) => string
    getLevelColor: (level: string) => string
    teachers: Array<{
      id: string
      name: string
      teacherNo: string
      department?: string | null
    }>
  }) {
    // 计算是否即将截止 (小于3天)
    const isUrgent = competition.deadline.getTime() - new Date().getTime() < 3 * 24 * 60 * 60 * 1000
    // 计算报名进度百分比
    const percent = Math.min(100, Math.round(((competition.currentParticipants || 0) / (competition.maxParticipants || 1)) * 100))

    return (
      <Card className="group hover:shadow-lg transition-all duration-300 hover:-translate-y-1">
        <CardHeader>
          <div className="flex justify-between items-start gap-4">
            <CardTitle className="text-lg leading-tight group-hover:text-blue-600 transition-colors line-clamp-2">
              {competition.name}
            </CardTitle>
            <div className="flex gap-2 flex-wrap">
              {competition.category && (
                <Badge variant="secondary" className={getCategoryColor(competition.category)}>
                  {getCategoryLabel(competition.category)}
                </Badge>
              )}
              {competition.level && (
                <Badge variant="secondary" className={getLevelColor(competition.level)}>
                  {competition.level}
                </Badge>
              )}
            </div>
          </div>
          <CardDescription className="line-clamp-3">
            {competition.description || '暂无赛事详细介绍'}
          </CardDescription>
        </CardHeader>
        
        <CardContent className="space-y-4">
          {/* 时间信息 */}
          <div className="flex items-center gap-4 text-sm text-gray-600">
            <div className="flex items-center gap-1">
              <Calendar className="h-4 w-4" />
              <span className={isUrgent ? 'text-red-600 font-semibold' : ''}>
                截止: {formatDate(competition.deadline)}
              </span>
            </div>
          </div>

          {/* 人数进度 */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">报名进度</span>
              <span className="font-medium">
                {competition.currentParticipants || 0}/{competition.maxParticipants}
              </span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div 
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${percent}%` }}
              />
            </div>
          </div>

          {/* 操作按钮 */}
          <div className="flex gap-2">
            <Button variant="outline" size="sm" asChild className="flex-1">
              <Link href={`/competitions/${competition.id}`}>
                查看详情
              </Link>
            </Button>
            <Button size="sm" className="flex-1" disabled={competition.isExpired}>
              {competition.isExpired ? '已截止' : '立即报名'}
            </Button>
          </div>
        </CardContent>
      </Card>
    )
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-white p-8">
        <div className="max-w-7xl mx-auto">
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-4 text-gray-600">加载中...</p>
          </div>
        </div>
      </div>
    )
  }

  const categories = ['TECHNICAL', 'PROGRAMMING', 'AI', 'LANGUAGE', 'INNOVATION']

  return (
    <div className="min-h-screen bg-white p-8">
      <div className="max-w-7xl mx-auto">
        {/* 页面标题 */}
        <div className="text-center mb-12">
          <h1 className="text-4xl font-bold text-gray-900 mb-4">竞赛大厅</h1>
          <p className="text-lg text-gray-600">探索各类竞赛，挑战自我，展现才华</p>
        </div>

        {/* Tabs组件 - 使用客户端渲染避免水合问题 */}
        <Tabs defaultValue="all" className="w-full block space-y-6">
          <TabsList className="mb-8 flex w-full flex-wrap justify-center items-center gap-3 bg-transparent h-auto max-h-20 p-0">
            <TabsTrigger value="all" className="h-10 flex items-center justify-center whitespace-nowrap rounded-full px-6 border border-gray-200 shadow-sm data-[state=active]:bg-blue-600 data-[state=active]:text-white data-[state=active]:border-blue-600 data-[state=active]:shadow-md transition-all">
              全部比赛
            </TabsTrigger>
            {categories.map(category => (
              <TabsTrigger 
                key={`tab-${category}`} 
                value={category} 
                className="h-10 flex items-center justify-center whitespace-nowrap rounded-full px-6 border border-gray-200 shadow-sm data-[state=active]:bg-blue-600 data-[state=active]:text-white data-[state=active]:border-blue-600 data-[state=active]:shadow-md transition-all"
              >
                {getCategoryLabel(category)}
              </TabsTrigger>
            ))}
          </TabsList>

          {/* 全部比赛内容 */}
          <TabsContent value="all" className="mt-0 w-full outline-none">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {competitions.length > 0 ? (
                competitions.map((competition) => (
                  <CompetitionCard 
                    key={competition.id} 
                    competition={competition}
                    formatDate={formatDate}
                    getCategoryColor={getCategoryColor}
                    getCategoryLabel={getCategoryLabel}
                    getLevelColor={getLevelColor}
                    teachers={teachers}
                  />
                ))
              ) : (
                <div className="col-span-full text-center py-12">
                  <div className="text-gray-500">
                    暂无比赛数据
                  </div>
                </div>
              )}
            </div>
          </TabsContent>

          {/* 各分类比赛内容 */}
          {categories.map(category => (
            <TabsContent key={`content-${category}`} value={category} className="mt-0 w-full outline-none">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {competitions
                  .filter((c) => c.category === category)
                  .length > 0 ? (
                  competitions
                  .filter((c) => c.category === category)
                  .map((competition) => (
                    <CompetitionCard 
                      key={competition.id} 
                      competition={competition}
                      formatDate={formatDate}
                      getCategoryColor={getCategoryColor}
                      getCategoryLabel={getCategoryLabel}
                      getLevelColor={getLevelColor}
                      teachers={teachers}
                    />
                  ))
                ) : (
                  <div className="col-span-full text-center py-12">
                    <div className="text-gray-500">
                      暂无此类比赛
                    </div>
                  </div>
                )}
              </div>
            </TabsContent>
          ))}
        </Tabs>
      </div>
    </div>
  )
}
